import React from "react";

function ReasonModal({
  open,
  title,
  description,
  placeholder,
  confirmLabel,
  value,
  onChange,
  onClose,
  onConfirm
}) {
  if (!open) {
    return null;
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-violet-950/35 px-4 py-6 backdrop-blur-sm">
      <div className="w-full max-w-md rounded-[28px] border border-violet-100 bg-white p-8 text-center shadow-[0_30px_80px_rgba(76,29,149,0.25)]">
        <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-rose-50 text-rose-500">
          <svg viewBox="0 0 24 24" className="h-8 w-8" fill="none" stroke="currentColor" strokeWidth="2.2">
            <circle cx="12" cy="12" r="9" />
            <path d="m15 9-6 6" />
            <path d="m9 9 6 6" />
          </svg>
        </div>

        <h2 className="mt-5 text-2xl font-semibold text-violet-950">{title}</h2>
        <p className="mt-3 text-sm leading-6 text-slate-500">{description}</p>

        <div className="mt-7 text-left">
          <label className="block text-xs font-semibold uppercase tracking-[0.22em] text-violet-400">
            Reason for cancellation
          </label>
          <textarea
            rows="5"
            value={value}
            onChange={(event) => onChange(event.target.value)}
            placeholder={placeholder}
            className="mt-3 w-full rounded-2xl border border-violet-200 bg-violet-50 px-4 py-3 text-sm text-slate-700 outline-none transition placeholder:text-slate-400 focus:border-violet-400 focus:bg-white"
          />
        </div>

        <button
          type="button"
          onClick={onConfirm}
          className="mt-7 w-full rounded-2xl bg-violet-700 px-5 py-3.5 text-sm font-semibold text-white transition hover:bg-violet-800"
        >
          {confirmLabel}
        </button>

        <button
          type="button"
          onClick={onClose}
          className="mt-4 text-sm font-medium text-slate-500 transition hover:text-violet-700"
        >
          Go Back
        </button>
      </div>
    </div>
  );
}

export default ReasonModal;
